INSERT INTO "public"."journey_steps" ("id", "journey_id", "day_number", "step_order", "title", "content_type", "content", "created_at") VALUES
	('c6bce8ea-15a0-48e4-8328-965536addd8e', '00000000-0000-0000-0000-000000000021', 1, 1, 'Willkommen bei AscendOS', 'info', '{"body": "Schön, dass du da bist. AscendOS führt dich ab heute durch deinen Arbeitstag. Diese Woche gehen wir gemeinsam Schritt für Schritt — danach übernimmt dein täglicher Plan."}', '2026-07-22 14:07:56.985994+00'),
	('af5c946f-7d72-4a12-851a-b91e0bf6eaf7', '00000000-0000-0000-0000-000000000021', 1, 2, 'Profil vervollständigen', 'task', '{"cta": "Zum Profil", "body": "Ergänze unter Mehr dein Profilbild und deine Telefonnummer, damit dein Team dich erkennt.", "link": "/mehr"}', '2026-07-22 14:07:56.985994+00'),
	('a463a032-f32e-4cb1-89dd-7a625a25e877', '00000000-0000-0000-0000-000000000021', 1, 3, 'WayToMoon öffnen', 'tool', '{"body": "WayToMoon ist unser Onboarding für Interessenten — schau es dir einmal selbst komplett an, damit du weißt, was deine Kontakte später sehen.", "tool_key": "waytomoon"}', '2026-07-22 14:07:56.985994+00'),
	('85c96540-3669-463d-ab7c-b7422308ec80', '00000000-0000-0000-0000-000000000021', 1, 4, 'Teamgruppe beitreten', 'task', '{"cta": "Bin drin", "body": "Tritt unserer Team-WhatsApp-Gruppe bei — den Link bekommst du von deinem Sponsor."}', '2026-07-22 14:07:56.985994+00'),
	('9c648b0c-7038-4fd0-a948-4fb8b73be67e', '00000000-0000-0000-0000-000000000021', 1, 5, 'Sponsor kontaktieren', 'task', '{"body": "Schreib deinem Sponsor eine kurze Nachricht: Du bist gestartet und freust dich auf die erste Woche. Ihr vereinbart am besten direkt euren ersten Check-in."}', '2026-07-22 14:07:56.985994+00'),
	('3d58df20-12a6-4a7c-bc3e-1eeafca0e663', '00000000-0000-0000-0000-000000000021', 2, 1, 'Firmenpräsentation ansehen', 'tool', '{"body": "Sieh dir unsere Firmenpräsentation vollständig an — sie ist das Herzstück jedes Interessenten-Gesprächs.", "tool_key": "presentation"}', '2026-07-22 14:07:56.985994+00'),
	('70fe856f-6f2a-4315-9525-a75b7b5cbad3', '00000000-0000-0000-0000-000000000021', 2, 2, 'Business Fit Check selbst machen', 'tool', '{"body": "Durchlaufe den Business Fit Check einmal selbst. So verstehst du, wie sich deine Interessenten dabei fühlen.", "tool_key": "fitcheck"}', '2026-07-22 14:07:56.985994+00'),
	('1bb6e69e-a022-4711-81e4-1c539bfef48a', '00000000-0000-0000-0000-000000000021', 3, 1, 'Social-Media-Grundlagen', 'info', '{"body": "Heute geht es um deinen Auftritt: authentisch, persönlich, ohne Werbeversprechen. Was wir posten — und was nie — findest du in der Team-Schulung. Frag Ascent nach unseren Social-Media-Regeln."}', '2026-07-22 14:07:56.985994+00'),
	('8ce4b77c-122d-4815-92b7-0aa2ffce3c74', '00000000-0000-0000-0000-000000000021', 3, 2, 'Ersten Beitrag planen', 'task', '{"body": "Plane einen persönlichen Beitrag über deinen Start — keine Produktwerbung, nur deine Geschichte."}', '2026-07-22 14:07:56.985994+00'),
	('e9d6a69f-7ee5-4bb2-b262-164dd8d6b3fb', '00000000-0000-0000-0000-000000000021', 4, 1, 'Duftparty verstehen', 'info', '{"body": "Die Duftparty ist unser stärkstes Erlebnis-Format. Frag Ascent: \"Wie läuft eine Duftparty ab?\" — er erklärt dir den kompletten Ablauf aus unseren Team-Unterlagen."}', '2026-07-22 14:07:56.985994+00'),
	('c6f2614f-f1d7-4f64-84d8-af30f0d560d2', '00000000-0000-0000-0000-000000000021', 5, 1, 'Deine ersten Kontakte', 'task', '{"cta": "Kontakt anlegen", "body": "Lege heute deine ersten drei Kontakte an: Menschen, denen du Chogan von Herzen zeigen würdest.", "link": "/kontakte/neu"}', '2026-07-22 14:07:56.985994+00'),
	('8a45939f-00b3-4bb6-8ae4-1d7925cfa8a8', '00000000-0000-0000-0000-000000000021', 6, 1, 'Follow-ups verstehen', 'info', '{"body": "Der Erfolg liegt im Nachfassen. Ab morgen zeigt dir dein Daily Plan automatisch, wen du wann kontaktierst — heute lernst du das Prinzip: kurz, ehrlich, ohne Druck."}', '2026-07-22 14:07:56.985994+00'),
	('f57e57d1-84cf-468f-a55b-f95f2428e14a', '00000000-0000-0000-0000-000000000021', 6, 2, 'Erstes Follow-up senden', 'task', '{"cta": "Zu den Kontakten", "body": "Melde dich bei einem deiner drei Kontakte mit einer persönlichen Nachricht. Dokumentiere es danach am Kontakt.", "link": "/kontakte"}', '2026-07-22 14:07:56.985994+00'),
	('1fab9bab-a6a3-4da3-a9a5-95935a6c8276', '00000000-0000-0000-0000-000000000021', 7, 1, 'Dein erstes Recruiting-Gespräch', 'task', '{"body": "Wähle deinen wärmsten Kontakt und teile die Firmenpräsentation. Bereite dich mit Ascent vor: \"Bereite mich auf das Gespräch vor.\" Ab morgen übernimmt dein Daily Command Center."}', '2026-07-22 14:07:56.985994+00');


